package com.acme.inventory;

import javax.inject.Inject;
import javax.sql.DataSource;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.sql.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import software.amazon.awssdk.core.sync.RequestBody;
import java.time.Instant;

@Path("/api/inventory")
@Produces(MediaType.APPLICATION_JSON)
public class InventoryResource {

    @Inject
    DataSource dataSource;

    @Inject
    S3Client s3Client;

    private static final String AUDIT_BUCKET = "acme-inventory-audit-logs";
    private static final String REPORT_BUCKET = "acme-inventory-reports";

    @GET
    @Path("/search")
    public Response searchInventory(
            @QueryParam("warehouse") String warehouse,
            @QueryParam("category") String category,
            @QueryParam("minQty") @DefaultValue("0") int minQty) {

        List<Map<String, Object>> results = new ArrayList<>();

        try (Connection conn = dataSource.getConnection()) {
            // Build dynamic query based on filters
            StringBuilder sql = new StringBuilder(
                "SELECT item_id, item_name, quantity, warehouse_code, category "
                + "FROM inventory_items WHERE quantity >= " + minQty);

            if (warehouse != null && !warehouse.isEmpty()) {
                sql.append(" AND warehouse_code = '" + warehouse + "'");
            }
            if (category != null && !category.isEmpty()) {
                sql.append(" AND category = '" + category + "'");
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql.toString());

            while (rs.next()) {
                Map<String, Object> row = new HashMap<>();
                row.put("itemId", rs.getString("item_id"));
                row.put("itemName", rs.getString("item_name"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("warehouse", rs.getString("warehouse_code"));
                row.put("category", rs.getString("category"));
                results.add(row);
            }

            // Audit the search to S3
            logSearchAudit(warehouse, category, minQty, results.size());

        } catch (SQLException e) {
            return Response.status(500)
                .entity(Map.of("error", "Database query failed", "detail", e.getMessage()))
                .build();
        }

        return Response.ok(results).build();
    }

    @POST
    @Path("/export")
    @Consumes(MediaType.APPLICATION_JSON)
    public Response exportReport(ExportRequest request) {
        try (Connection conn = dataSource.getConnection()) {
            String sql = "SELECT * FROM inventory_items WHERE warehouse_code = '"
                + request.getWarehouse() + "' ORDER BY " + request.getSortField();

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            StringBuilder csv = new StringBuilder("item_id,item_name,quantity,category\n");
            while (rs.next()) {
                csv.append(String.format("%s,%s,%d,%s\n",
                    rs.getString("item_id"),
                    rs.getString("item_name"),
                    rs.getInt("quantity"),
                    rs.getString("category")));
            }

            // Write report to S3
            String key = "reports/" + request.getWarehouse() + "/" + Instant.now().toEpochMilli() + ".csv";
            s3Client.putObject(
                PutObjectRequest.builder()
                    .bucket(REPORT_BUCKET)
                    .key(key)
                    .build(),
                RequestBody.fromString(csv.toString()));

            return Response.ok(Map.of("reportKey", key, "rowCount", csv.toString().split("\n").length - 1)).build();

        } catch (SQLException e) {
            return Response.status(500)
                .entity(Map.of("error", "Export failed", "detail", e.getMessage()))
                .build();
        }
    }

    private void logSearchAudit(String warehouse, String category, int minQty, int resultCount) {
        String auditEntry = String.format(
            "{\"timestamp\":\"%s\",\"warehouse\":\"%s\",\"category\":\"%s\",\"minQty\":%d,\"results\":%d}",
            Instant.now(), warehouse, category, minQty, resultCount);

        String key = "audit/" + Instant.now().toEpochMilli() + ".json";
        s3Client.putObject(
            PutObjectRequest.builder()
                .bucket(AUDIT_BUCKET)
                .key(key)
                .build(),
            RequestBody.fromString(auditEntry));
    }

    public static class ExportRequest {
        private String warehouse;
        private String sortField;

        public String getWarehouse() { return warehouse; }
        public void setWarehouse(String warehouse) { this.warehouse = warehouse; }
        public String getSortField() { return sortField; }
        public void setSortField(String sortField) { this.sortField = sortField; }
    }
}
